    pub(crate) fn stop<'a>(&self, this_value: JsWrapper<'a, Self>) -> JsWrapper<'a, Self> {
        Self::self_stop(self.self_ref.get().this_ptr(), self.global.bun_vm());
        this_value
    }
}

pub(crate) fn call_matcher<'a>(
    &self,
    this_value: JsWrapper<'a, Self>,
    cx: &mut JsScope<'a>,
    callee: JsLocal<'a>,
    arguments: &'a [JsLocal<'a>],
    matcher: fn(JsWrapper<'a, Self>, &mut JsScope<'a>, &'a [JsLocal<'a>]) -> JsResult<JSValue>,
) -> JsResult<JSValue> {
    matcher(this_value, cx, arguments)
