class Database {
  constructor(
    filename: string,
    options?:
      | number
      | {
          readonly?: boolean;
          create?: boolean;
          readwrite?: boolean;
          safeIntegers?: boolean;
          strict?: boolean;
        },
  );

  query<ReturnType, ParamsType>(sql: string): Statement<ReturnType, ParamsType>;
  prepare<ReturnType, ParamsType>(sql: string, params?: ParamsType): Statement<ReturnType, ParamsType>;
  run(sql: string, params?: SQLQueryBindings): { lastInsertRowid: number | bigint; changes: number };
  exec = this.run;
  clearQueryCache(): void;

  transaction(insideTransaction: (...args: any) => void): CallableFunction & {
    deferred: (...args: any) => void;
    immediate: (...args: any) => void;
    exclusive: (...args: any) => void;
  };

  function(name: string, fn: (...args: any[]) => SQLFunctionResult): this;
  function(name: string, options: FunctionOptions, fn: (...args: any[]) => SQLFunctionResult): this;
  aggregate<T>(
    name: string,
    options: FunctionOptions & {
      start?: T | (() => T);
      step: (accumulator: T, ...args: any[]) => T | void;
      inverse?: (accumulator: T, ...args: any[]) => T | void;
      result?: (accumulator: T) => SQLFunctionResult;
    },
  ): this;

  onInsert: UpdateHook | null;
  onUpdate: UpdateHook | null;
  onDelete: UpdateHook | null;

  readonly inTransaction: boolean;
  readonly filename: string;

  serialize(name?: string): Buffer;
  static deserialize(
    serialized: TypedArray | ArrayBufferLike,
    options?: boolean | { readonly?: boolean; strict?: boolean; safeIntegers?: boolean },
  ): Database;

  loadExtension(extension: string, entryPoint?: string): void;
  static setCustomSQLite(path: string): boolean;
  fileControl(op: number, arg?: ArrayBufferView | number | null): number;
  fileControl(zDbName: string, op: number, arg?: ArrayBufferView | number | null): number;

  close(throwOnError?: boolean): void;
}

class Statement<ReturnType, ParamsType> {
  all(...params: ParamsType[]): ReturnType[];
  get(...params: ParamsType[]): ReturnType | null;
  run(...params: ParamsType[]): {
    lastInsertRowid: number | bigint;
    changes: number;
  };
  values(...params: ParamsType[]): unknown[][];
  raw(...params: ParamsType[]): (Uint8Array | null)[][];
  iterate(...params: ParamsType[]): IterableIterator<ReturnType>;
  [Symbol.iterator](): IterableIterator<ReturnType>;

  safeIntegers(enabled: boolean): this; // return integers as bigint
  safeIntegers(): boolean;

  finalize(): void; // destroy statement and clean up resources
  toString(): string; // serialize to SQL

  columnNames: string[]; // the column names of the result set
  columnTypes: string[]; // types based on actual values in first row (runs the statement; read-only statements only)
  declaredTypes: (string | null)[]; // types from CREATE TABLE schema
  paramsCount: number; // the number of parameters expected by the statement
  reader: boolean; // whether the statement returns rows
  readonly: boolean; // whether the statement makes no direct change to the database
  isFinalized: boolean;
  native: any; // the native object representing the statement

  as<T>(Class: new (...args: any[]) => T): Statement<T, ParamsType>;
}

type SQLQueryBindings =
  | string
  | bigint
  | TypedArray
  | ArrayBufferLike
  | number
  | boolean
  | null
  | Record<string, string | bigint | TypedArray | ArrayBufferLike | number | boolean | null>;

type SQLFunctionResult = string | bigint | TypedArray | ArrayBufferLike | number | boolean | null | undefined | void;

type FunctionOptions = {
  varargs?: boolean;
  deterministic?: boolean;
  directOnly?: boolean;
  safeIntegers?: boolean;
};

type UpdateHook = (
  this: Database,
  database: Database,
  tableName: string,
  rowid: number | bigint,
  schemaName: string,
) => void;

